export interface UnitChoice {
  readonly id: string;
  readonly nightlyRate: number;
}

export interface StayRequest {
  readonly guestName: string;
  readonly phone: string;
  readonly adults: number;
  readonly children: number;
  readonly arrivalDay: number;
  readonly departureDay: number;
  readonly units: readonly UnitChoice[];
  readonly advance: number;
  readonly discount: number;
}

export interface StayQuote {
  readonly nights: number;
  readonly subtotal: number;
  readonly discount: number;
  readonly total: number;
  readonly advance: number;
  readonly balance: number;
  readonly unitIds: readonly string[];
}

export function calculateStayQuote(request: StayRequest): StayQuote {
  if (typeof request.guestName !== "string" || request.guestName.trim().length === 0 || typeof request.phone !== "string" || request.phone.trim().length === 0) {
    throw new TypeError("guestName and phone must be non-blank");
  }
  if (!Number.isInteger(request.adults) || !Number.isInteger(request.children) || !Number.isInteger(request.arrivalDay) || !Number.isInteger(request.departureDay)) {
    throw new TypeError("counts and days must be integers");
  }
  if (request.adults <= 0 || request.children < 0 || request.departureDay <= request.arrivalDay) {
    throw new RangeError("invalid occupancy or date range");
  }
  if (!Array.isArray(request.units) || request.units.length === 0) {
    throw new RangeError("at least one unit is required");
  }
  const ids = new Set<string>();
  let nightlyTotal = 0;
  for (const unit of request.units) {
    if (typeof unit.id !== "string" || unit.id.trim().length === 0 || typeof unit.nightlyRate !== "number" || !Number.isFinite(unit.nightlyRate)) {
      throw new TypeError("invalid unit");
    }
    if (unit.nightlyRate < 0 || ids.has(unit.id)) {
      throw new RangeError("rates must be non-negative and IDs unique");
    }
    ids.add(unit.id);
    nightlyTotal += unit.nightlyRate;
  }
  for (const amount of [request.advance, request.discount]) {
    if (typeof amount !== "number" || !Number.isFinite(amount)) {
      throw new TypeError("amounts must be finite numbers");
    }
    if (amount < 0) throw new RangeError("amounts must be non-negative");
  }
  const nights = request.departureDay - request.arrivalDay + 1;
  const subtotal = nights * nightlyTotal;
  if (request.discount > subtotal) throw new RangeError("discount exceeds subtotal");
  const total = subtotal - request.discount;
  if (request.advance > total) throw new RangeError("advance exceeds total");
  const unitIds = Object.freeze(request.units.map((unit) => unit.id));
  return Object.freeze({ nights, subtotal, discount: request.discount, total, advance: request.advance, balance: total - request.advance, unitIds });
}

