import { calculateStayQuote, type StayRequest } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectThrows(fn: () => unknown, ctor: typeof TypeError | typeof RangeError, message: string): void {
  try { fn(); } catch (error) { if (error instanceof ctor) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

function validRequest(): StayRequest {
  return {
    guestName: '  Guest  ', phone: ' 555-0100 ', adults: 2, children: 0,
    arrivalDay: 10, departureDay: 13,
    units: [{ id: ' suite ', nightlyRate: 100 }, { id: 'cabin', nightlyRate: 50 }],
    advance: 120, discount: 30,
  };
}

const mutable = validRequest() as {
  guestName: string; phone: string; adults: number; children: number;
  arrivalDay: number; departureDay: number;
  units: { id: string; nightlyRate: number }[]; advance: number; discount: number;
};
const quote = calculateStayQuote(mutable);
equal(quote.nights, 3, 'nights use exclusive departure');
equal(quote.subtotal, 450, 'subtotal');
equal(quote.discount, 30, 'discount');
equal(quote.total, 420, 'discounted total');
equal(quote.advance, 120, 'advance');
equal(quote.balance, 300, 'balance');
assert(quote.unitIds.length === 2 && quote.unitIds[0] === ' suite ' && quote.unitIds[1] === 'cabin', 'unit order and exact IDs');
assert(Object.isFrozen(quote), 'quote is frozen');
assert(Object.isFrozen(quote.unitIds), 'unit ID array is frozen');

mutable.units[0].id = 'changed';
mutable.units.push({ id: 'new', nightlyRate: 1 });
mutable.discount = 0;
equal(quote.unitIds.length, 2, 'quote does not retain unit array');
equal(quote.unitIds[0], ' suite ', 'quote copies IDs');
equal(quote.discount, 30, 'quote is stable after request mutation');

const boundary = calculateStayQuote({
  guestName: 'G', phone: 'P', adults: 1, children: 0,
  arrivalDay: -2, departureDay: -1,
  units: [{ id: 'u', nightlyRate: 0 }], advance: 0, discount: 0,
});
equal(boundary.nights, 1, 'negative day indices are valid when ordered');
equal(boundary.subtotal, 0, 'zero rate subtotal');
equal(boundary.total, 0, 'zero total');
equal(boundary.balance, 0, 'zero balance');

expectThrows(() => calculateStayQuote({ ...validRequest(), guestName: ' ' }), TypeError, 'blank guest name');
expectThrows(() => calculateStayQuote({ ...validRequest(), phone: '\t' }), TypeError, 'blank phone');
expectThrows(() => calculateStayQuote({ ...validRequest(), adults: '2' } as unknown as StayRequest), TypeError, 'non-number adults');
expectThrows(() => calculateStayQuote({ ...validRequest(), adults: 0 }), RangeError, 'zero adults');
expectThrows(() => calculateStayQuote({ ...validRequest(), children: -1 }), RangeError, 'negative children');
expectThrows(() => calculateStayQuote({ ...validRequest(), departureDay: 10 }), RangeError, 'non-positive stay');
expectThrows(() => calculateStayQuote({ ...validRequest(), units: [] }), RangeError, 'no units');
expectThrows(() => calculateStayQuote({ ...validRequest(), units: [{ id: 'x', nightlyRate: 1 }, { id: 'x', nightlyRate: 2 }] }), RangeError, 'duplicate unit IDs');
expectThrows(() => calculateStayQuote({ ...validRequest(), units: [{ id: ' ', nightlyRate: 1 }] }), TypeError, 'blank unit ID');
expectThrows(() => calculateStayQuote({ ...validRequest(), units: [{ id: 'x', nightlyRate: -1 }] }), RangeError, 'negative rate');
expectThrows(() => calculateStayQuote({ ...validRequest(), units: [{ id: 'x', nightlyRate: Number.NaN }] }), TypeError, 'non-finite rate');
expectThrows(() => calculateStayQuote({ ...validRequest(), discount: 451 }), RangeError, 'discount exceeds subtotal');
expectThrows(() => calculateStayQuote({ ...validRequest(), discount: 30, advance: 421 }), RangeError, 'advance exceeds total');

